function edgeKey(left, right) {
  return left <= right ? `${left}|${right}` : `${right}|${left}`;
}

export class Graph {
  constructor() {
    this._nodes = new Map();
    this._adjacency = new Map();
  }

  addNode(node) {
    if (!this._nodes.has(node)) {
      this._nodes.set(node, true);
      this._adjacency.set(node, new Map());
    }
  }

  addWeightedEdge(left, right, weight) {
    this.addNode(left);
    this.addNode(right);

    this._adjacency.get(left).set(right, { weight });
    if (left !== right) {
      this._adjacency.get(right).set(left, { weight });
    }
  }

  addWeightedEdgesFrom(weightedEdges) {
    for (const [left, right, weight] of weightedEdges) {
      this.addWeightedEdge(left, right, weight);
    }
  }

  nodes() {
    return Array.from(this._nodes.keys());
  }

  neighbors(node) {
    return Array.from(this._adjacency.get(node)?.keys() ?? []);
  }

  hasEdge(left, right) {
    return this._adjacency.get(left)?.has(right) ?? false;
  }

  getWeight(left, right) {
    return this._adjacency.get(left)?.get(right)?.weight;
  }

  degree(node) {
    let total = 0;

    for (const neighbor of this.neighbors(node)) {
      total += neighbor === node ? 2 : 1;
    }

    return total;
  }

  edges() {
    const seen = new Set();
    const edges = [];

    for (const [left, neighbors] of this._adjacency.entries()) {
      for (const [right, attributes] of neighbors.entries()) {
        const key = edgeKey(left, right);
        if (seen.has(key)) {
          continue;
        }

        seen.add(key);
        edges.push({
          u: left,
          v: right,
          weight: attributes.weight,
        });
      }
    }

    return edges;
  }

  numberOfEdges() {
    return this.edges().length;
  }
}

