export function bfsEdges(graph, source) {
  const visited = new Set([source]);
  const queue = [source];
  const edges = [];
  let index = 0;

  while (index < queue.length) {
    const current = queue[index];
    index += 1;

    for (const neighbor of graph.neighbors(current)) {
      if (visited.has(neighbor)) {
        continue;
      }

      visited.add(neighbor);
      queue.push(neighbor);
      edges.push([current, neighbor]);
    }
  }

  return edges;
}

export function dfsEdges(graph, source) {
  const visited = new Set([source]);
  const edges = [];
  const stack = [
    {
      node: source,
      neighbors: graph.neighbors(source),
      index: 0,
    },
  ];

  while (stack.length > 0) {
    const frame = stack[stack.length - 1];

    if (frame.index >= frame.neighbors.length) {
      stack.pop();
      continue;
    }

    const neighbor = frame.neighbors[frame.index];
    frame.index += 1;

    if (visited.has(neighbor)) {
      continue;
    }

    visited.add(neighbor);
    edges.push([frame.node, neighbor]);
    stack.push({
      node: neighbor,
      neighbors: graph.neighbors(neighbor),
      index: 0,
    });
  }

  return edges;
}

