export function formatPythonFloat(value) {
  if (Number.isNaN(value)) {
    return 'nan';
  }

  if (!Number.isFinite(value)) {
    if (value === Infinity) {
      return 'inf';
    }
    if (value === -Infinity) {
      return '-inf';
    }
  }

  return Number.isInteger(value) ? value.toFixed(1) : String(value);
}

export function formatPythonBool(value) {
