function extractMin(queue) {
  let bestIndex = 0;

  for (let index = 1; index < queue.length; index += 1) {
    const candidate = queue[index];
    const currentBest = queue[bestIndex];

    if (
      candidate.distance < currentBest.distance ||
      (candidate.distance === currentBest.distance && candidate.order < currentBest.order)
    ) {
      bestIndex = index;
    }
  }

  return queue.splice(bestIndex, 1)[0];
}

export function dijkstraPathAndLength(graph, source, target) {
  if (source === target) {
    return {
      length: 0,
      path: [source],
      lengthIsFloat: false,
    };
  }

  const settled = new Map();
  const seen = new Map([[source, 0]]);
  const parents = new Map();
  const queue = [{ node: source, distance: 0, order: 0 }];
  let order = 1;

  while (queue.length > 0) {
    const current = extractMin(queue);
    if (settled.has(current.node)) {
      continue;
    }

    settled.set(current.node, current.distance);
    if (current.node === target) {
      break;
    }

    for (const neighbor of graph.neighbors(current.node)) {
      if (settled.has(neighbor)) {
        continue;
      }

      const candidateDistance = current.distance + graph.getWeight(current.node, neighbor);
      const bestSeen = seen.get(neighbor);
      if (bestSeen !== undefined && candidateDistance >= bestSeen) {
        continue;
      }

      seen.set(neighbor, candidateDistance);
      parents.set(neighbor, current.node);
      queue.push({
        node: neighbor,
        distance: candidateDistance,
        order,
      });
      order += 1;
    }
  }

  if (!settled.has(target)) {
    throw new Error('No path between the requested nodes.');
  }

  const path = [];
  let currentNode = target;

  while (currentNode !== undefined) {
    path.push(currentNode);
    if (currentNode === source) {
      break;
    }

    currentNode = parents.get(currentNode);
  }

  path.reverse();

  return {
    length: settled.get(target),
    path,
    lengthIsFloat: true,
  };
}

