import { Graph } from '../graph/Graph.mjs';

class DisjointSet {
  constructor(nodes) {
    this.parent = new Map();

    for (const node of nodes) {
      this.parent.set(node, node);
    }
  }

  find(node) {
    const parent = this.parent.get(node);
    if (parent === node) {
      return node;
    }

    const root = this.find(parent);
    this.parent.set(node, root);
    return root;
  }

  union(left, right) {
    const leftRoot = this.find(left);
    const rightRoot = this.find(right);

    if (leftRoot !== rightRoot) {
      this.parent.set(rightRoot, leftRoot);
    }
  }
}

export function minimumSpanningTree(graph) {
  const spanningTree = new Graph();
  const nodes = graph.nodes();

  for (const node of nodes) {
    spanningTree.addNode(node);
  }

  const disjointSet = new DisjointSet(nodes);
  const edges = graph
    .edges()
    .filter((edge) => edge.u !== edge.v)
    .sort((left, right) => left.weight - right.weight);

  for (const edge of edges) {
    if (disjointSet.find(edge.u) === disjointSet.find(edge.v)) {
      continue;
    }

    disjointSet.union(edge.u, edge.v);
    spanningTree.addWeightedEdge(edge.u, edge.v, edge.weight);
  }

  return spanningTree;
}

