export function pyFloat(value) {
  return new PyFloat(value);
}

export function pyTuple(items) {
  return { __pyTuple__: true, items };
}

export function toNumber(value) {
  return value instanceof PyFloat ? value.value : value;
}

function formatFloat(value) {
  if (Object.is(value, -0)) {
    return "0.0";
  }

  if (Number.isInteger(value)) {
    return `${value}.0`;
  }

  return String(value);
}

export function toPythonString(value) {
  if (value instanceof PyFloat) {
    return formatFloat(value.value);
  }

  if (value && value.__pyTuple__ === true) {
    const rendered = value.items.map((item) => toPythonString(item)).join(", ");
    const suffix = value.items.length === 1 ? "," : "";
    return `(${rendered}${suffix})`;
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => toPythonString(item)).join(", ")}]`;
  }

  if (typeof value === "boolean") {
    return value ? "True" : "False";
  }

  if (typeof value === "bigint") {
    return value.toString();
  }

  if (typeof value === "number") {
