import { pyFloat, pyTuple, toNumber } from "./format.mjs";
import { MinPriorityQueue } from "./priority_queue.mjs";

function buildPath(parentByNode, target) {
  const path = [target];
  let current = target;

  while (parentByNode.has(current)) {
    current = parentByNode.get(current);
    path.push(current);
  }

  path.reverse();
  return path;
}

function dijkstra(graph, source, target) {
  if (source === target) {
    return { distance: 0, path: [source] };
  }

  const distanceByNode = new Map([[source, 0]]);
  const parentByNode = new Map();
  let pushOrder = 0;

  const queue = new MinPriorityQueue((left, right) => {
    if (left.distance !== right.distance) {
      return left.distance - right.distance;
    }

    return left.order - right.order;
  });

  queue.push({ node: source, distance: 0, order: pushOrder });

  while (!queue.isEmpty()) {
    const current = queue.pop();

    if (current.distance !== distanceByNode.get(current.node)) {
      continue;
    }

    if (current.node === target) {
      break;
    }

    for (const neighbor of graph.neighbors(current.node)) {
      const candidate = current.distance + toNumber(graph.getEdgeWeight(current.node, neighbor));

      if (!distanceByNode.has(neighbor) || candidate < distanceByNode.get(neighbor)) {
        distanceByNode.set(neighbor, candidate);
        parentByNode.set(neighbor, current.node);
        pushOrder += 1;
        queue.push({ node: neighbor, distance: candidate, order: pushOrder });
      }
    }
  }

  const distance = distanceByNode.get(target);
  return { distance, path: buildPath(parentByNode, target) };
}

export function dijkstraPathLength(graph, source, target) {
  const result = dijkstra(graph, source, target);
  return result.distance === 0 ? 0 : pyFloat(result.distance);
}

export function dijkstraPath(graph, source, target) {
  return dijkstra(graph, source, target).path;
}

export function bfsEdges(graph, source) {
  const edges = [];
  const queue = [source];
  const seen = new Set([source]);

  while (queue.length > 0) {
    const node = queue.shift();

    for (const neighbor of graph.neighbors(node)) {
      if (seen.has(neighbor)) {
        continue;
      }

      seen.add(neighbor);
      queue.push(neighbor);
      edges.push(pyTuple([node, neighbor]));
    }
  }

  return edges;
}

export function dfsEdges(graph, source) {
  const edges = [];
  const seen = new Set([source]);
  const stack = [{ node: source, neighbors: graph.neighbors(source), index: 0 }];

  while (stack.length > 0) {
    const frame = stack[stack.length - 1];

    if (frame.index >= frame.neighbors.length) {
      stack.pop();
      continue;
    }

    const neighbor = frame.neighbors[frame.index];
    frame.index += 1;

    if (seen.has(neighbor)) {
      continue;
    }

    seen.add(neighbor);
    edges.push(pyTuple([frame.node, neighbor]));
    stack.push({ node: neighbor, neighbors: graph.neighbors(neighbor), index: 0 });
  }

  return edges;
}

